  // --- state 2: working -------------------------------------------------------
  function renderWorking() {
    const j = S.job;
    const failed = j.status === "failed";
    const title = failed ? "The run failed" : j.engine === "devin" ? "Devin is working on it" : "Detailing " + j.project;
    app.innerHTML = `
