        ${j.engine === "devin" ? `<div class="devin-line"><div class="msg">${esc(j.devin_message || "starting session…")}</div><div class="acu">${j.devin_acus != null ? `${j.devin_acus} ACU` : ""}</div></div>` : ""}
        ${failed ? `<div class="err">${esc(j.error || "unknown error")}</div>` : ""}
        <div class="foot">
